head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[autoComplete > P > allowEmptySubmission]<br/>입력값이 없을 때 interactionEnterKey 속성의 검색키 입력 시 아이템을 동적으로 요청할지 설정합니다.",
    "validation" : [
        "interactionMode='true' 인 경우에 동작합니다.",
        "true 설정 시, 입력값이 없을 때 interactionEnterKey 속성의 검색키를 입력하면 빈 문자열로 아이템 데이터를 요청합니다.",
        "interactionEnterKey='false' 이면 입력창이 편집 모드로 전환된 후 입력값을 모두 삭제한 경우도 아이템 데이터를 요청합니다.",
        "false 설정 시, 입력값이 없으면 interactionEnterKey 속성의 검색키를 입력해도 아이템 데이터를 요청하지 않습니다.",
        "미설정 시, 입력값이 없으면 interactionEnterKey 속성의 검색키를 입력해도 아이템 데이터를 요청하지 않습니다.",
        "편집 모드일때 입력값 검색이 된 후 편집 모드를 해제하지 않고 입력값을 모두 삭제하면 allowEmptySubmission 속성값에 관계없이 다음과 같이 동작합니다. interactionEnterKey='true' 이면 입력값이 모두 삭제된 후 Enter 키 입력 시 아이템 데이터를 요청합니다.",
        "편집 모드일때 입력값 검색이 된 후 편집 모드를 해제하지 않고 입력값을 모두 삭제하면 allowEmptySubmission 속성값에 관계없이 다음과 같이 동작합니다. interactionEnterKey='false' 이면 입력값이 모두 삭제되면 아이템 데이터를 요청합니다."
    ]
}

// submissionFunc 가 검색 결과로 추가할 아이템 (초기 아이템은 두지 않아 입력창이 빈 상태로 시작)
scwin.arrCity = [
    { "label" : "Seoul", "value" : "SEL" },
    { "label" : "Seongnam", "value" : "SNM" },
    { "label" : "Busan", "value" : "PUS" },
    { "label" : "Jeju", "value" : "CJU" }
];

// submissionFunc 호출 기록 (요청 확인 버튼 클릭 시 출력 후 비움)
scwin.arrRequest = [];



scwin.onpageload = function () {
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // con 기본값 : allowEmptySubmission=true, interactionMode=true, interactionEnterKey=true
    con_allowEmptySubmission.setValue("2");
    con_interactionMode.setValue("2");
    con_interactionEnterKey.setValue("2");

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') target1.remove();

    $c.gcm.createLabel('label="[전제]\n- 아이템 : Seoul, Seongnam, Busan, Jeju\n- submissionFunc 는 검색어로 시작하는 아이템(빈 문자열이면 전체)을 목록에 표시\n- 검색키 : interactionEnterKey=true 는 Enter 키, false 는 입력값 변경 또는 목록이 닫힌 상태의 아래 화살표키\n- 직전 검색어와 같으면 다시 요청하지 않으므로 절차마다 Target 재생성 후 시작\n[절차]\n1. 빈 입력창 클릭 -> 검색키(Enter 또는 아래 화살표키) -> 요청 확인\n2. Se 입력(interactionEnterKey=true 는 Enter 추가) -> 목록에서 Seoul 클릭 -> 요청 확인(편집 모드 해제) -> 입력창 클릭 -> Ctrl+A 후 Backspace 로 모두 삭제(interactionEnterKey=true 는 Enter 추가) -> 요청 확인\n3. Se 입력(interactionEnterKey=true 는 Enter 추가) -> 목록이 열린 상태에서 Backspace 로 모두 삭제(interactionEnterKey=true 는 Enter 추가) -> 요청 확인\n[확인] 직전 요청 확인 이후의 요청 횟수와 검색어(keyCode)"', '', 'label1');

    scwin.arrRequest = [];

    let properties = {
        allowEmptySubmission : con_allowEmptySubmission.getText(),
        interactionMode : con_interactionMode.getText(),
        interactionEnterKey : con_interactionEnterKey.getText(),
        submissionFunc : "scwin.searchItem",
    }

    let cList = $c.gcm.createCList(properties);

    let strTarget = '';
    strTarget += '<w2:autoComplete ' + $c.gcm.getNameSpace() + ' ' + cList + ' style="width:200px; height:30px;">';
    strTarget += '<w2:choices></w2:choices>';
    strTarget += '</w2:autoComplete>';

    await $p.dynamicCreate("target1", "autoComplete", strTarget, $c.gcm.getTestGroup());
}



// interactionMode=true 일때 아이템 데이터 요청 함수 : 호출 기록 후 검색어로 시작하는 아이템(빈 문자열이면 전체)을 목록에 표시
// initAutoComplete() 는 입력창 값까지 비워 입력값 삭제 절차가 성립하지 않으므로 아이템만 제거하는 removeAll() 사용
scwin.searchItem = function (searchStr, keyCode) {
    scwin.arrRequest.push((searchStr === "" ? "(빈 문자열)" : searchStr) + "(" + keyCode + ")");
    target1.removeAll();
    scwin.arrCity.forEach(function (item) {
        if (item.label.indexOf(searchStr) === 0) {
            target1.addItem(item.label, item.value);
        }
    });
    target1.openTable();
};



// 직전 확인 이후의 아이템 데이터 요청 횟수와 검색어 출력 후 기록 비움 (validation 1 ~ 7)
scwin.btn_getRequest_onclick = function (e) {
    let strResult = "요청 횟수 : " + scwin.arrRequest.length;
    if (scwin.arrRequest.length > 0) {
        strResult += " -> 검색어(keyCode) : " + scwin.arrRequest.join(" / ");
    }
    wf_body_bottom.getObj("scwin").setReturnValue(strResult);
    scwin.arrRequest = [];
};
